import XCTest
@testable import NexusCore

final class ClipboardSensitiveTypePolicyTests: XCTestCase {
    func testSensitiveMarkerOnAnyPasteboardItemBlocksCapture() {
        let ordinary = ["public.utf8-plain-text", "public.file-url"]
        for marker in [
            "org.nspasteboard.ConcealedType",
            "org.nspasteboard.TransientType",
            "org.nspasteboard.AutoGeneratedType"
        ] {
            XCTAssertTrue(ClipboardSensitiveTypePolicy.shouldSkip(
                typeNamesByItem: [ordinary, ["public.utf8-plain-text", marker]]
            ))
            XCTAssertTrue(ClipboardSensitiveTypePolicy.shouldSkip(
                typeNamesByItem: [[marker], ordinary]
            ))
        }
    }

    func testOrdinaryClipboardTypesAreNotExcludedWithoutMarker() {
        XCTAssertFalse(ClipboardSensitiveTypePolicy.shouldSkip(
            typeNamesByItem: [
                ["public.utf8-plain-text"],
                ["public.file-url", "public.png"]
            ]
        ))
        XCTAssertFalse(ClipboardSensitiveTypePolicy.shouldSkip(
            typeNamesByItem: []
        ))
    }

    func testMarkerMatchingIsSpecificToAdvertisedType() {
        XCTAssertFalse(ClipboardSensitiveTypePolicy.shouldSkip(
            typeNamesByItem: [[
                "com.example.ConcealedType",
                "org.nspasteboard.ConcealedType.fake"
            ]]
        ))
    }
}
